<?php
namespace App\Services;use App\Models\MobileMutation;use App\Models\User;use Illuminate\Support\Facades\DB;
class MobileMutationService{public function run(User $user,string $requestId,string $operation,callable $callback):array{return DB::transaction(function()use($user,$requestId,$operation,$callback){$existing=MobileMutation::where('user_id',$user->id)->where('client_request_id',$requestId)->lockForUpdate()->first();if($existing)return['body'=>$existing->response_body,'status'=>$existing->response_status,'replayed'=>true];[$body,$status]=$callback();MobileMutation::create(['user_id'=>$user->id,'client_request_id'=>$requestId,'operation'=>$operation,'response_status'=>$status,'response_body'=>$body]);return['body'=>$body,'status'=>$status,'replayed'=>false];});}}
